#pragma once
#include <stdint.h>
#include <stdbool.h>

/* FreeLang type kinds */
typedef enum {
    FL_TYPE_VOID,
    FL_TYPE_BOOL,
    FL_TYPE_I32,
    FL_TYPE_I64,
    FL_TYPE_F32,
    FL_TYPE_F64,
    FL_TYPE_STRING,
    FL_TYPE_ARRAY,
    FL_TYPE_POINTER,
    FL_TYPE_STRUCT,
    FL_TYPE_UNKNOWN,
} FlTypeKind;

typedef struct FlType {
    FlTypeKind kind;

    union {
        /* FL_TYPE_ARRAY: array element type and length */
        struct {
            struct FlType *element_type;
            int length;  /* -1 = unsized */
        };

        /* FL_TYPE_POINTER: pointee type */
        struct {
            struct FlType *pointee_type;
        } ptr;

        /* FL_TYPE_STRUCT: struct name */
        struct {
            const char *name;
        } st;
    };
} FlType;

/* Create type instances */
FlType *fl_type_void(void);
FlType *fl_type_bool(void);
FlType *fl_type_i32(void);
FlType *fl_type_i64(void);
FlType *fl_type_f32(void);
FlType *fl_type_f64(void);
FlType *fl_type_string(void);
FlType *fl_type_array(FlType *element, int length);
FlType *fl_type_pointer(FlType *pointee);
FlType *fl_type_struct(const char *name);

/* Convert FreeLang type to C type string */
const char *fl_type_to_c_string(FlType *ty);

/* Type size in bytes */
int fl_type_size(FlType *ty);

/* Check type equality */
bool fl_type_equals(FlType *a, FlType *b);

/* Free type (recursively) */
void fl_type_free(FlType *ty);

