#include "types.h"

/* ========================================
 * FreeLang AST Node Definitions
 * ======================================== */

typedef enum {
    /* Statements */
    STMT_VAR_DECL,
    STMT_EXPR,
    STMT_RETURN,
    STMT_IF,
    STMT_WHILE,
    STMT_FOR,
    STMT_BLOCK,

    /* Expressions */
    EXPR_LITERAL,       /* int, float, string */
    EXPR_VAR,           /* variable reference */
    EXPR_BINARY,        /* a + b, a * b, etc */
    EXPR_UNARY,         /* -a, !a, *a, &a */
    EXPR_CALL,          /* fn(args) */
    EXPR_INDEX,         /* arr[i] */
    EXPR_MEMBER,        /* obj.field */
} NodeKind;

typedef struct Expr Expr;
typedef struct Stmt Stmt;

/* ---- Expressions ---- */

typedef struct {
    long long ival;  /* int literal */
} LiteralInt;

typedef struct {
    double fval;     /* float literal */
} LiteralFloat;

typedef struct {
    const char *sval;  /* string literal */
} LiteralString;

typedef struct {
    const char *name;  /* variable name */
} VarRef;

typedef struct {
    Expr *left;
    Expr *right;
    const char *op;    /* "+", "-", "*", "/", etc */
} BinaryOp;

typedef struct {
    Expr *operand;
    const char *op;    /* "-", "!", "*", "&" */
} UnaryOp;

typedef struct {
    const char *func_name;
    Expr **args;
    int arg_count;
} FuncCall;

typedef struct {
    Expr *array;
    Expr *index;
} IndexOp;

typedef struct {
    Expr *object;
    const char *field;
} MemberOp;

typedef struct Expr {
    NodeKind kind;
    FlType *type;  /* resolved type */

    union {
        LiteralInt lit_int;
        LiteralFloat lit_float;
        LiteralString lit_string;
        VarRef var;
        BinaryOp binary;
        UnaryOp unary;
        FuncCall call;
        IndexOp index;
        MemberOp member;
    };
} Expr;

/* ---- Statements ---- */

typedef struct {
    const char *name;
    FlType *type;
    Expr *init;        /* initializer, may be NULL */
} VarDecl;

typedef struct {
    Expr *value;       /* may be NULL for void return */
} ReturnStmt;

typedef struct {
    Expr *condition;
    Stmt *then_body;
    Stmt *else_body;   /* may be NULL */
} IfStmt;

typedef struct {
    Expr *condition;
    Stmt *body;
} WhileStmt;

typedef struct {
    const char *var_name;
    Expr *start;
    Expr *end;
    Stmt *body;
} ForStmt;

typedef struct {
    Stmt **stmts;
    int count;
} BlockStmt;

typedef struct Stmt {
    NodeKind kind;

    union {
        VarDecl var_decl;
        Expr *expr;        /* for STMT_EXPR */
        ReturnStmt ret;
        IfStmt if_stmt;
        WhileStmt while_stmt;
        ForStmt for_stmt;
        BlockStmt block;
    };
} Stmt;

/* ---- Functions ---- */

typedef struct {
    const char *name;
    const char **param_names;
    FlType **param_types;
    int param_count;
    FlType *return_type;
    Stmt *body;
    int is_extern;
} FuncDef;

/* ---- Program ---- */

typedef struct {
    FuncDef **functions;
    int func_count;
    const char **includes;
    int include_count;
} Program;

/* ---- Constructors ---- */

Expr *expr_literal_int(long long value);
Expr *expr_literal_float(double value);
Expr *expr_literal_string(const char *value);
Expr *expr_var(const char *name);
Expr *expr_binary(Expr *left, Expr *right, const char *op);
Expr *expr_unary(Expr *operand, const char *op);
Expr *expr_call(const char *func_name, Expr **args, int arg_count);
Expr *expr_index(Expr *array, Expr *index);
Expr *expr_member(Expr *object, const char *field);

Stmt *stmt_var_decl(const char *name, FlType *type, Expr *init);
Stmt *stmt_return(Expr *value);
Stmt *stmt_if(Expr *cond, Stmt *then_b, Stmt *else_b);
Stmt *stmt_while(Expr *cond, Stmt *body);
Stmt *stmt_for(const char *var, Expr *start, Expr *end, Stmt *body);
Stmt *stmt_block(Stmt **stmts, int count);
Stmt *stmt_expr(Expr *expr);

FuncDef *func_def_new(const char *name,
                      const char **param_names,
                      FlType **param_types,
                      int param_count,
                      FlType *return_type,
                      Stmt *body);

Program *program_new(FuncDef **funcs, int func_count);

/* ---- Cleanup ---- */

void expr_free(Expr *e);
void stmt_free(Stmt *s);
void func_def_free(FuncDef *f);
void program_free(Program *p);

