#include "../include/types.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* Type instance constructors */

FlType *fl_type_void(void) {
    FlType *ty = malloc(sizeof(FlType));
    ty->kind = FL_TYPE_VOID;
    return ty;
}

FlType *fl_type_bool(void) {
    FlType *ty = malloc(sizeof(FlType));
    ty->kind = FL_TYPE_BOOL;
    return ty;
}

FlType *fl_type_i32(void) {
    FlType *ty = malloc(sizeof(FlType));
    ty->kind = FL_TYPE_I32;
    return ty;
}

FlType *fl_type_i64(void) {
    FlType *ty = malloc(sizeof(FlType));
    ty->kind = FL_TYPE_I64;
    return ty;
}

FlType *fl_type_f32(void) {
    FlType *ty = malloc(sizeof(FlType));
    ty->kind = FL_TYPE_F32;
    return ty;
}

FlType *fl_type_f64(void) {
    FlType *ty = malloc(sizeof(FlType));
    ty->kind = FL_TYPE_F64;
    return ty;
}

FlType *fl_type_string(void) {
    FlType *ty = malloc(sizeof(FlType));
    ty->kind = FL_TYPE_STRING;
    return ty;
}

FlType *fl_type_array(FlType *element, int length) {
    FlType *ty = malloc(sizeof(FlType));
    ty->kind = FL_TYPE_ARRAY;
    ty->element_type = element;
    ty->length = length;
    return ty;
}

FlType *fl_type_pointer(FlType *pointee) {
    FlType *ty = malloc(sizeof(FlType));
    ty->kind = FL_TYPE_POINTER;
    ty->ptr.pointee_type = pointee;
    return ty;
}

FlType *fl_type_struct(const char *name) {
    FlType *ty = malloc(sizeof(FlType));
    ty->kind = FL_TYPE_STRUCT;
    ty->st.name = strdup(name);
    return ty;
}

/* Convert FreeLang type to C type string */
const char *fl_type_to_c_string(FlType *ty) {
    if (!ty) return "void";

    switch (ty->kind) {
        case FL_TYPE_VOID:
            return "void";
        case FL_TYPE_BOOL:
            return "int";  /* C bool via 0/1 */
        case FL_TYPE_I32:
            return "int";
        case FL_TYPE_I64:
            return "long";
        case FL_TYPE_F32:
            return "float";
        case FL_TYPE_F64:
            return "double";
        case FL_TYPE_STRING:
            return "char*";
        case FL_TYPE_POINTER: {
            static char buf[256];
            const char *pointee_str = fl_type_to_c_string(ty->ptr.pointee_type);
            snprintf(buf, sizeof(buf), "%s*", pointee_str);
            return buf;
        }
        case FL_TYPE_ARRAY: {
            static char buf[256];
            const char *elem_str = fl_type_to_c_string(ty->element_type);
            if (ty->length < 0) {
                snprintf(buf, sizeof(buf), "%s[]", elem_str);
            } else {
                snprintf(buf, sizeof(buf), "%s[%d]", elem_str, ty->length);
            }
            return buf;
        }
        case FL_TYPE_STRUCT:
            return ty->st.name;
        case FL_TYPE_UNKNOWN:
        default:
            return "???";
    }
}

/* Type size in bytes (simplified) */
int fl_type_size(FlType *ty) {
    if (!ty) return 0;

    switch (ty->kind) {
        case FL_TYPE_VOID:
            return 0;
        case FL_TYPE_BOOL:
        case FL_TYPE_I32:
            return 4;
        case FL_TYPE_I64:
            return 8;
        case FL_TYPE_F32:
            return 4;
        case FL_TYPE_F64:
            return 8;
        case FL_TYPE_STRING:
        case FL_TYPE_POINTER:
            return 8;  /* 64-bit pointer */
        case FL_TYPE_ARRAY:
            return fl_type_size(ty->element_type) * ty->length;
        case FL_TYPE_STRUCT:
            return 0;  /* Unknown struct size */
        case FL_TYPE_UNKNOWN:
        default:
            return 0;
    }
}

/* Type equality */
bool fl_type_equals(FlType *a, FlType *b) {
    if (!a || !b) return a == b;
    if (a->kind != b->kind) return false;

    switch (a->kind) {
        case FL_TYPE_POINTER:
            return fl_type_equals(a->ptr.pointee_type, b->ptr.pointee_type);
        case FL_TYPE_ARRAY:
            return fl_type_equals(a->element_type, b->element_type) &&
                   a->length == b->length;
        case FL_TYPE_STRUCT:
            return strcmp(a->st.name, b->st.name) == 0;
        default:
            return a->kind == b->kind;
    }
}

/* Free type recursively */
void fl_type_free(FlType *ty) {
    if (!ty) return;

    switch (ty->kind) {
        case FL_TYPE_POINTER:
            fl_type_free(ty->ptr.pointee_type);
            break;
        case FL_TYPE_ARRAY:
            fl_type_free(ty->element_type);
            break;
        case FL_TYPE_STRUCT:
            free((void *)ty->st.name);
            break;
        default:
            break;
    }

    free(ty);
}

